    v := private.save_pack($pk${"code":"nisia-trowel3","title":"Trowel Occupations L3","course":"trowel3","standard":"6570-05","version":"1.1","option":null,"content":{"topics":[{"id":"trowel3/unit-102","name":"102 Conforming to general health, safety and welfare in the workplace","optional":false,"ksbs":[{"code":"102.1.1","text":"Comply with information from workplace inductions and any health, safety and welfare briefings attended relevant to the occupational area"},{"code":"102.1.2","text":"Use health and safety control equipment safely to carry out the activity in accordance with legislation and organisational requirements"},{"code":"102.1.3","text":"Comply with statutory requirements, safety notices and warning notices displayed within the workplace and/or on equipment"},{"code":"102.1.4","text":"State why and when health and safety control equipment, identified by the principles of protection, should be used relating to types, purpose and limitations of each type, the work situation, occupational use and the general work environment, in relation to:"},{"code":"102.1.5","text":"State how the health and safety control equipment relevant to the work should be used in accordance with the given instructions"},{"code":"102.1.6","text":"State which types of health, safety and welfare legislation, notices and warning signs are relevant to the occupational area and associated equipment"},{"code":"102.1.7","text":"State why health, safety and welfare legislation, notices and warning signs are relevant to the occupational area"},{"code":"102.1.8","text":"State how to comply with control measures that have been identified by risk assessments and safe systems of work"},{"code":"102.2.1","text":"Report any hazards created by changing circumstances within the workplace in accordance with organisational procedures"},{"code":"102.2.2","text":"List typical hazards associated with the work environment and occupational area in relation to: resources, substances, asbestos, equipment, obstructions, storage, services and work activities"},{"code":"102.2.3","text":"List the current health and safety executive top ten safety risks"},{"code":"102.2.4","text":"List the current health and safety executive top five health risks"},{"code":"102.2.5","text":"State how changing circumstances within the workplace could cause hazards"},{"code":"102.2.6","text":"State the methods used for reporting changed circumstances, hazards and incidents in the workplace"},{"code":"102.3.1","text":"Interpret and comply with given instructions to maintain safe systems of work and quality working practices"},{"code":"102.3.2","text":"Contribute to discussions by offering/providing feedback relating to health, safety and welfare"},{"code":"102.3.3","text":"Contribute to the maintenance of workplace welfare facilities in accordance with workplace welfare procedures"},{"code":"102.3.4","text":"Safely store health and safety control equipment in accordance with given instructions"},{"code":"102.3.5","text":"Dispose of waste and/or consumable items in accordance with legislation"},{"code":"102.3.6","text":"State the organisational policies and procedures for health, safety and welfare, in relation to:"},{"code":"102.3.7","text":"State the appropriate types of fire extinguishers relevant to the work"},{"code":"102.3.8","text":"State how and when the different types of fire extinguishers are used in accordance with legislation and official guidance"},{"code":"102.4.1","text":"Demonstrate behaviour which shows personal responsibility for general workplace health, safety and welfare"},{"code":"102.4.2","text":"State how personal behaviour demonstrates responsibility for general workplace health, safety and welfare, in relation to:"},{"code":"102.4.3","text":"Give examples of how the behaviour and actions of individuals could affect others within the workplace"},{"code":"102.5.1","text":"Provide appropriate support for security arrangements in accordance with approved procedures:"},{"code":"102.5.2","text":"State how security arrangements are implemented in relation to:"}]},{"id":"trowel3/unit-234","name":"234 Erecting masonry cladding in the workplace","optional":false,"ksbs":[{"code":"234.1.1","text":"Interpret and extract relevant information from:"},{"code":"234.1.2","text":"Comply with information and/or instructions derived from risk assessments and method statements"},{"code":"234.1.3","text":"Describe the organisational procedures developed to report and rectify inappropriate information and unsuitable resources and how they are implemented"},{"code":"234.1.4","text":"Describe different types of information, their source and how they are interpreted in relation to:"},{"code":"234.2.1","text":"Describe their responsibilities regarding potential accidents, health hazards and the environment, whilst working:"},{"code":"234.2.2","text":"Describe the organisational security procedures for tools, equipment and personal belongings in relation to:"},{"code":"234.2.3","text":"Explain what the accident reporting procedures are and who is responsible for making reports"},{"code":"234.3.1","text":"Use health and safety control equipment and access equipment safely to carry out the activity in accordance with current legislation and organisational requirements when erecting masonry cladding"},{"code":"234.3.2","text":"Demonstrate compliance with given information and relevant legislation when erecting masonry cladding in relation to the following:"},{"code":"234.3.3","text":"Explain why and when health and safety control equipment, identified by the principles of prevention, should be used, relating to erecting masonry cladding, and the types, purpose and limitations of each type, the work situation and general work environment, in relation to:"},{"code":"234.3.4","text":"Describe how the relevant health and safety control equipment should be used in accordance with the given instructions"},{"code":"234.3.5","text":"Describe how emergencies should be responded to in accordance with organisational authorisation and personal skills when involved with:"},{"code":"234.4.1","text":"Select resources associated with own work in relation to:"},{"code":"234.4.2","text":"Describe the characteristics, quality, uses, sustainability, limitations and defects associated with the resources in relation to:"},{"code":"234.4.3","text":"Describe how to confirm that the resources and materials conform to the specification"},{"code":"234.4.4","text":"Describe how the resources should be used correctly and how problems associated with the resources are reported"},{"code":"234.4.5","text":"Explain why the organisational procedures have been developed and how they are used for the selection of required resources"},{"code":"234.4.6","text":"Describe any potential hazards associated with the resources and methods of work"},{"code":"234.4.7","text":"Describe how to calculate quantity, length, area and wastage of materials associated with the method and procedure to erect masonry cladding"},{"code":"234.5.1","text":"Protect the work and its surrounding area from damage in accordance with safe working practices and organisational procedures"},{"code":"234.5.2","text":"Maintain a clear and tidy work space"},{"code":"234.5.3","text":"Dispose of waste in accordance with current legislation"},{"code":"234.5.4","text":"Describe how to protect work from damage and the purpose of protection in relation to:"},{"code":"234.5.5","text":"Explain why the disposal of waste should be carried out safely in accordance with:"},{"code":"234.6.1","text":"Demonstrate completion of the work within the estimated allocated time"},{"code":"234.6.2","text":"Describe the purpose of the work programme and explain why deadlines should be kept in relation to:"},{"code":"234.7.1","text":"Demonstrate the following work skills when erecting masonry cladding:"},{"code":"234.7.2","text":"Use and maintain hand and power tools and equipment"},{"code":"234.7.3","text":"Erect brick and block and/or local material cladding to given working instructions, including the formation of openings and joint finishes, for at least one of the following structures:"},{"code":"234.7.4","text":"Describe how to apply safe and healthy work practices, follow procedures, report problems and establish the authority needed to rectify them, to:"},{"code":"234.7.5","text":"Describe the needs of other occupations and how to communicate effectively within a team when erecting masonry cladding"},{"code":"234.7.6","text":"Describe how to maintain the tools and equipment used when erecting masonry cladding"}]},{"id":"trowel3/unit-235","name":"235 Erecting masonry structures in the workplace","optional":false,"ksbs":[{"code":"235.1.1","text":"Interpret and extract relevant information from:"},{"code":"235.1.2","text":"Comply with information and/or instructions derived from risk assessments and method statements"},{"code":"235.1.3","text":"Describe the organisational procedures developed to report and rectify inappropriate information and unsuitable resources and how they are implemented"},{"code":"235.1.4","text":"Describe different types of information, their source and how they are interpreted in relation to:"},{"code":"235.2.1","text":"Describe their responsibilities regarding potential accidents, health hazards and the environment, whilst working:"},{"code":"235.2.2","text":"Describe the organisational security procedures for tools, equipment and personal belongings in relation to:"},{"code":"235.2.3","text":"Explain what the accident reporting procedures are and who is responsible for making reports"},{"code":"235.3.1","text":"Use health and safety control equipment safely and comply with the methods of work to carry out the activity in accordance with current legislation and organisational requirements when erecting masonry structures"},{"code":"235.3.2","text":"Demonstrate compliance with given information and relevant legislation when erecting masonry structures in relation to the following:"},{"code":"235.3.3","text":"Explain why and when health and safety control equipment, identified by the principles of prevention, should be used, relating to erecting masonry structures, and the types, purpose and limitations of each type, the work situation and general work environment, in relation to:"},{"code":"235.3.4","text":"Describe how the relevant health and safety control equipment should be used in accordance with the given working instructions"},{"code":"235.3.5","text":"Describe how emergencies should be responded to in accordance with organisational authorisation and personal skills when involved with:"},{"code":"235.4.1","text":"Select resources associated with own work in relation to:"},{"code":"235.4.2","text":"Describe the characteristics, quality, uses, sustainability, limitations and defects associated with the resources in relation to:"},{"code":"235.4.3","text":"Describe how to confirm that the resources and materials conform to the specification"},{"code":"235.4.4","text":"Describe how the resources should be used correctly and how problems associated with the resources are reported"},{"code":"235.4.5","text":"Explain why the organisational procedures have been developed and how they are used for the selection of required resources"},{"code":"235.4.6","text":"Describe any potential hazards associated with the resources and methods of work"},{"code":"235.4.7","text":"Describe how to calculate quantity, length, area and wastage of materials associated with the method/procedure to erect masonry structures"},{"code":"235.5.1","text":"Protect the work and its surrounding area from damage in accordance with safe working practices and organisational procedures"},{"code":"235.5.2","text":"Maintain a clear and tidy work space"},{"code":"235.5.3","text":"Dispose of waste in accordance with current legislation"},{"code":"235.5.4","text":"Describe how to protect work from damage and the purpose of protection in relation to:"},{"code":"235.5.5","text":"Explain why the disposal of waste should be carried out safely in accordance with:"},{"code":"235.6.1","text":"Demonstrate completion of the work within the estimated allocated time"},{"code":"235.6.2","text":"Describe the purpose of the work programme and explain why deadlines should be kept in relation to:"},{"code":"235.7.1","text":"Demonstrate the following work skills when erecting masonry structures:"},{"code":"235.7.2","text":"Use and maintain hand and power tools, and equipment"},{"code":"235.7.3","text":"Erect masonry in brick and block and/or local materials to given working instructions for the following:"},{"code":"235.7.4","text":"Describe how to apply safe and healthy work practices, follow procedures, report problems and establish the authority needed to rectify them, to:"},{"code":"235.7.5","text":"Describe the needs of other occupations and how to communicate effectively within a team when erecting masonry structures"},{"code":"235.7.6","text":"Describe how to maintain the tools and equipment used when erecting masonry structures"}]},{"id":"trowel3/unit-300","name":"300 Confirming work activities and resources for an occupational work area in the workplace","optional":false,"ksbs":[{"code":"300.1.1","text":"Identify work activities, assess required resources and plan the sequence of work"},{"code":"300.1.2","text":"Identify work activities and formulate a plan for their own sequence of work"},{"code":"300.1.3","text":"Explain the types of work relative to the occupational area and how to identify different work activities"},{"code":"300.1.4","text":"Explain methods of assessing the resources needed from a range of available information"},{"code":"300.1.5","text":"Explain the required information and the different methods used to prepare a work programme relative to the occupational area"},{"code":"300.2.1","text":"Seek advice and clarity from appropriate sources on resources available and the alternatives that can be used for the work when required resources are not available"},{"code":"300.2.2","text":"Explain the different sources and methods that can be used to obtain clarification and advice when the required resources are not available"},{"code":"300.3.1","text":"Assess progress of work against project requirements, taking into account external factors relating to:"},{"code":"300.3.2","text":"Explain different methods of evaluating work activities against the following project requirements:"},{"code":"300.3.3","text":"Evaluate the requirements of significant external factors that could affect the progress of work, in relation to:"},{"code":"300.4.1","text":"Determine work activities that have an influence on each other"},{"code":"300.4.2","text":"Evaluate which work activities make the best use of available resources in relation to:"},{"code":"300.4.3","text":"Explain different methods and sources that can identify which work activities influence each other"},{"code":"300.4.4","text":"Describe how to determine the sequence of work activities and how long each work activity will take"},{"code":"300.4.5","text":"Describe what zero and low carbon requirements are"},{"code":"300.4.6","text":"Explain how work activities and different ways of using resources can impact on zero and low carbon requirements, and make a positive contribution to the environment"},{"code":"300.5.1","text":"Evaluate project progress against the work programme to identify any changed circumstances"},{"code":"300.5.2","text":"Inform line management and/or customers on the type and extent of any required changes to the work programme"},{"code":"300.5.3","text":"Explain how to identify possible alterations to the work programme to meet changed circumstances relating to:"},{"code":"300.5.4","text":"Explain how to assess contractual/work effects resulting from alterations to the work programme"},{"code":"300.5.5","text":"Explain the methods used to justify to decision makers on the effects resulting from alterations to the work programme"}]},{"id":"trowel3/unit-303","name":"303 Confirming the occupational method of work in the workplace","optional":false,"ksbs":[{"code":"303.1.1","text":"Interpret and extract information from:"},{"code":"303.1.2","text":"Explain how to summarise the following project data:"},{"code":"303.1.3","text":"Explain the different methods of assessing available project data"},{"code":"303.1.4","text":"Explain how to use project data to interpret the work method, in relation to:"},{"code":"303.2.1","text":"Collect and collate additional information from alternative sources to clarify the work to be carried out"},{"code":"303.2.2","text":"Explain different methods and techniques of obtaining additional information from the following alternative sources when available project data is insufficient:"},{"code":"303.3.1","text":"Examine potential work methods to carry out the occupational work activity"},{"code":"303.3.2","text":"Determine which work methods will make best use of relevant resources and meet health and safety requirements relating to technical and/or project criteria"},{"code":"303.3.3","text":"Explain how to identify work methods that make best use of resources and meet project, statutory and contractual requirements against technical criteria, in relation to:"},{"code":"303.3.4","text":"Explain how to identify work methods that make best use of resources and meet project, statutory and contractual requirements against project criteria, in relation to:"},{"code":"303.3.5","text":"Explain how different methods of work can achieve zero/low carbon outcomes"},{"code":"303.4.1","text":"Confirm the selected occupational work method that meets project, statutory and contractual requirements"},{"code":"303.4.2","text":"Communicate appropriately to relevant people on the selected occupational work method"},{"code":"303.4.3","text":"Describe the different techniques and methods of confirming and communicating work methods to relevant people"},{"code":"303.4.4","text":"Explain the principles of equality and diversity and how to apply them when working and communicating with others"}]},{"id":"trowel3/unit-313","name":"313 Erecting masonry to form architectural and decorative structures in the workplace","optional":false,"ksbs":[{"code":"313.1.1","text":"Interpret and extract relevant information from:"},{"code":"313.1.2","text":"Comply with information and/or instructions derived from risk assessments and method statements"},{"code":"313.1.3","text":"Describe the organisational procedures developed to report and rectify inappropriate information and unsuitable resources and how they are implemented"},{"code":"313.1.4","text":"Describe different types of information, their source and how they are interpreted in relation to:"},{"code":"313.2.1","text":"Describe their responsibilities regarding potential accidents, health hazards and the environment, whilst working:"},{"code":"313.2.2","text":"Describe the organisational security procedures for tools, equipment and personal belongings in relation to:"},{"code":"313.2.3","text":"Explain what the accident reporting procedures are and who is responsible for making reports"},{"code":"313.3.1","text":"Use health and safety control equipment and access equipment safely to carry out the activity in accordance with current legislation and organisational requirements when erecting masonry to form architectural and decorative structures"},{"code":"313.3.2","text":"Demonstrate compliance with given information and relevant legislation when erecting masonry to form architectural and decorative structures in relation to the following:"},{"code":"313.3.3","text":"Explain why and when health and safety control equipment, identified by the principles of prevention, should be used, relating to erecting masonry to form architectural and decorative, and the types, purpose and limitations of each type, the work situation and general work environment, in relation to:"},{"code":"313.3.4","text":"Describe how the relevant health and safety control equipment should be used in accordance with the given instructions"},{"code":"313.3.5","text":"Describe how emergencies should be responded to in accordance with organisational authorisation and personal skills when involved with:"},{"code":"313.4.1","text":"Select resources associated with own work in relation to:"},{"code":"313.4.2","text":"Describe the characteristics, quality, uses, sustainability, limitations and defects associated with the resources in relation to:"},{"code":"313.4.3","text":"Describe how to confirm that the resources and materials conform to the specification"},{"code":"313.4.4","text":"Describe how the resources should be used correctly and how problems associated with the resources are reported"},{"code":"313.4.5","text":"Explain why the organisational procedures have been developed and how they are used for the selection of required resources"},{"code":"313.4.6","text":"Describe any potential hazards associated with the resources and methods of work"},{"code":"313.4.7","text":"Describe how to calculate quantity, length, area and wastage of materials associated with the method and procedure to erect masonry to form architectural and decorative structures"},{"code":"313.5.1","text":"Protect the work and its surrounding area from damage in accordance with safe working practices and organisational procedures"},{"code":"313.5.2","text":"Maintain a clear and tidy work space"},{"code":"313.5.3","text":"Dispose of waste in accordance with current legislation"},{"code":"313.5.4","text":"Describe how to protect work from damage and the purpose of protection in relation to:"},{"code":"313.5.5","text":"Explain why the disposal of waste should be carried out safely in accordance with:"},{"code":"313.6.1","text":"Demonstrate completion of the work within the estimated allocated time"},{"code":"313.6.2","text":"Describe the purpose of the work programme and explain why deadlines should be kept in relation to:"},{"code":"313.7.1","text":"Demonstrate the following work skills when erecting masonry to form architectural and decorative structures:"},{"code":"313.7.2","text":"Use and maintain hand and power tools, and equipment"},{"code":"313.7.3","text":"Erect masonry in brick and block and/or local materials to given working instructions, to form architectural and decorative features including forming joint finishes, for at least three of the following :"},{"code":"313.7.4","text":"Describe how to apply safe and healthy work practices, follow procedures, report problems and establish the authority needed to rectify them, to:"},{"code":"313.7.5","text":"Describe the needs of other occupations and how to communicate effectively within a team when erecting masonry to form architectural and decorative structures"},{"code":"313.7.6","text":"Describe how to maintain the tools and equipment used when erecting masonry to form architectural and decorative structures"}]},{"id":"trowel3/unit-502","name":"502 Developing and maintaining good occupational working relationships in the workplace","optional":false,"ksbs":[{"code":"502.1.1","text":"Give appropriate advice and information to relevant people about the occupational work activities and/or associated occupations involved"},{"code":"502.1.2","text":"Apply the principles of equality and diversity by considering the needs of individuals when working and communicating with others"},{"code":"502.1.3","text":"Explain the methods and techniques used and personal attributes required to encourage and maintain working relationships that promote goodwill and trust with relevant people"},{"code":"502.1.4","text":"Explain the principles of equality and diversity and how to apply them when working and communicating with others"},{"code":"502.2.1","text":"Communicate on the following work activity information to relevant people following organisational procedures:"},{"code":"502.2.2","text":"Explain the different methods and techniques used to inform relevant people about work activities"},{"code":"502.2.3","text":"Explain the effects of not informing relevant people with the expected level of urgency"},{"code":"502.2.4","text":"Explain the different types of work activity related information and to what level of detail the following people would expect to receive:"},{"code":"502.3.1","text":"Give appropriate advice and information to relevant people about the different methods of carrying out occupational work activities to achieve the required outcome"},{"code":"502.3.2","text":"Explain the techniques of encouraging questions and/or requests for clarification and comments"},{"code":"502.3.3","text":"Explain the different ways of offering advice and help to different people about work activities, in relation to:"},{"code":"502.4.1","text":"Engage regular discussions with relevant people about the occupational work activity and/or other occupations involved"},{"code":"502.4.2","text":"Explain the methods of clarifying alternative proposals with relevant people"},{"code":"502.4.3","text":"Explain the methods of suggesting alternative proposals"},{"code":"502.5.1","text":"Examine and agree the work activities that satisfy all people involved and will meet the required outcome of the proposed method of work"},{"code":"502.5.2","text":"Explain the methods and techniques used to resolve differences of opinion in ways which minimise offence and maintain goodwill, trust and respect"}]},{"id":"trowel3/unit-701","name":"701 Setting out to form masonry structures in the workplace","optional":false,"ksbs":[{"code":"701.1.1","text":"Interpret and extract relevant information from:"},{"code":"701.1.2","text":"Comply with information and/or instructions derived from risk assessments and method statements"},{"code":"701.1.3","text":"Describe the organisational procedures developed to report and rectify inappropriate information and unsuitable resources and how they are implemented"},{"code":"70